const prepare = function ({ body, domain, reportDate }) {
  if (!body || typeof body !== "object" || !Array.isArray(body.keywords))
    throw new Error("SERPBear did not return a keywords array.");
  const summaries = body.keywords.map((keyword, index) => {
    if (
      !keyword ||
      typeof keyword !== "object" ||
      typeof keyword.keyword !== "string" ||
      !keyword.keyword.trim()
    )
      throw new Error("Keyword " + index + " has no keyword text.");
    if (keyword.domain !== domain)
      throw new Error("A keyword does not match the configured domain.");
    if (!Number.isInteger(keyword.position) || keyword.position < 0)
      throw new Error("A keyword has an invalid position.");
    const history = keyword.history ?? {};
    if (typeof history !== "object" || Array.isArray(history))
      throw new Error("A keyword has invalid history.");
    const observations = Object.entries(history)
      .map(([date, position]) => {
        const parsed = /^\d{4}-\d{2}-\d{2}$/.test(date) ? new Date(date + "T00:00:00Z") : null;
        if (
          !parsed ||
          !Number.isFinite(parsed.getTime()) ||
          parsed.toISOString().slice(0, 10) !== date ||
          !Number.isInteger(position) ||
          position < 0
        )
          throw new Error("A keyword has an invalid history observation.");
        return { date, position };
      })
      .sort((a, b) => a.date.localeCompare(b.date))
      .slice(-7);
    const ranked = observations.filter((observation) => observation.position > 0);
    const mean = ranked.length
      ? ranked.reduce((sum, observation) => sum + observation.position, 0) / ranked.length
      : null;
    const currentPosition = keyword.position === 0 ? null : keyword.position;
    const trend =
      currentPosition === null
        ? "not in top 100"
        : mean === null
          ? "insufficient ranked history"
          : currentPosition < mean
            ? "improving"
            : currentPosition > mean
              ? "declining"
              : "stable";
    return {
      keyword: keyword.keyword,
      device: typeof keyword.device === "string" ? keyword.device : "",
      country: typeof keyword.country === "string" ? keyword.country : "",
      currentPosition,
      averagePosition: mean === null ? null : Math.round(mean * 10) / 10,
      observations: observations.length,
      rankedObservations: ranked.length,
      trend,
      url: typeof keyword.url === "string" && keyword.url ? keyword.url : "not ranking",
    };
  });
  const prompt = `Here's the SEO ranking data for ${domain} as of ${reportDate} (UTC):\n\n${summaries.length ? summaries.map((keyword) => `Keyword: ${JSON.stringify(keyword.keyword)}\nDevice: ${keyword.device}\nCountry: ${keyword.country}\nCurrent Position: ${keyword.currentPosition ?? "not in top 100"}\nLatest-7-observation Ranked Average: ${keyword.averagePosition ?? "no ranked history"}\nObservations: ${keyword.observations}, ranked: ${keyword.rankedObservations}\nTrend: ${keyword.trend}\nRanking URL: ${keyword.url}\n`).join("\n") : "No tracked keywords were returned for this domain. Do not invent keyword rankings."}\n\nAn observation with position 0 means not in the top 100. The average excludes these observations; no numeric average is claimed for unranked history. These are the latest available history observations, not necessarily seven consecutive calendar days.\n\nPlease analyze this data and provide:\n1. Key observations about ranking performance\n2. Keywords showing the most improvement\n3. Keywords needing attention\n4. Suggested actions for improvement`;
  return {
    summaries,
    messages: [
      {
        role: "user",
        content:
          "You are an SEO expert. This is keyword data for my site. Can you summarize the data into a table and then give me some suggestions:" +
          prompt,
      },
    ],
  };
};

const scope = $("Prepare Report Scope").first().json;
return [
  {
    json: prepare({
      body: $input.first().json,
      domain: scope.domain,
      reportDate: scope.reportDate,
    }),
    pairedItem: { item: 0 },
  },
];

const prepare = function ({ domain, blog }) {
  if (typeof domain !== "string" || !domain.trim() || /[\s\/@:?#]/u.test(domain.trim()))
    throw new Error("Set the tracked SERPBear domain, without a protocol or path.");
  if (typeof blog !== "string" || !blog.trim()) throw new Error("Set the Baserow Blog label.");
  return {
    domain: domain.trim(),
    blog: blog.trim(),
    reportDate: new Date().toISOString().slice(0, 10),
  };
};

return [
  { json: prepare({ domain: "example.com", blog: "Example site" }), pairedItem: { item: 0 } },
];

const prepare = function ({ completion, reportDate, blog }) {
  const report = completion?.choices?.[0]?.message?.content;
  if (typeof report !== "string" || !report.trim())
    throw new Error("OpenRouter did not return report text.");
  return { report, row: { Date: reportDate, Note: report, Blog: blog } };
};

const scope = $("Prepare Report Scope").first().json;
return [
  {
    json: prepare({
      completion: $input.first().json,
      reportDate: scope.reportDate,
      blog: scope.blog,
    }).row,
    pairedItem: { item: 0 },
  },
];

const row = $input.first().json;
if (!Number.isInteger(row.id) || row.id <= 0)
  throw new Error("Baserow did not confirm a created row ID.");
return [{ json: row, pairedItem: { item: 0 } }];
